import json, re
from pathlib import Path

path = Path('Answers/annotation/numbering_record_claims_from_current.json')
items = json.loads(path.read_text(encoding='utf-8'))

marker_pattern = re.compile(
    r'ב?משפטים?(?![א-ת])\s*[:)]?\s*'
    r'([0-9]+(?:\s*-\s*[0-9]+)?(?:\s*(?:,|and)\s*[0-9]+(?:\s*-\s*[0-9]+)?)*)'
)

def parse_spec(spec):
    s = (spec or '').replace('and', ',')
    s = re.sub(r'[^0-9,\-]', '', s)
    out = set()
    for part in filter(None, s.split(',')):
        if '-' in part:
            a, b = part.split('-', 1)
            if a.isdigit() and b.isdigit():
                a, b = int(a), int(b)
                lo, hi = (a, b) if a <= b else (b, a)
                out.update(range(lo, hi + 1))
        elif part.isdigit():
            out.add(int(part))
    return out

def parse_ref_text(text):
    refs = set()
    for m in marker_pattern.finditer(text or ''):
        seq = m.group(1).replace('and', ',')
        for tok in filter(None, [x.strip() for x in seq.split(',')]):
            if '-' in tok:
                a, b = [x.strip() for x in tok.split('-', 1)]
                if a.isdigit() and b.isdigit():
                    a, b = int(a), int(b)
                    lo, hi = (a, b) if a <= b else (b, a)
                    refs.update(range(lo, hi + 1))
            elif tok.isdigit():
                refs.add(int(tok))
    return refs

subset = [x for x in items if x.get('expected_location_hint')]
print('checked_items:', len(subset))
print('record_ids:', [x['record_id'] for x in subset])

mismatches = []
for it in subset:
    rid = it['record_id']
    bad = parse_spec(it.get('claims_bad_numbering'))
    found = parse_ref_text(it.get('expected_location_hint'))
    ok = (bad == found)
    print(f"{rid} | bad={sorted(bad)} | hint_refs={sorted(found)} | ok={ok}")
    if not ok:
        mismatches.append({
            'record_id': rid,
            'bad': sorted(bad),
            'hint_refs': sorted(found),
            'missing': sorted(bad - found),
            'extra': sorted(found - bad),
        })

print('all_match:', len(mismatches) == 0)
print('mismatch_count:', len(mismatches))
if mismatches:
    print('mismatches:', mismatches)
