import json
import os
import re
import time
from pathlib import Path
from typing import Optional, Dict, Any

import requests
from dotenv import load_dotenv

ROOT = Path('.').resolve()
load_dotenv(ROOT / '.env')

INPUT_FILE = ROOT / 'Answers/annotation/regenerate_answer_only_input.json'
PROMPT_FILE = ROOT / 'Answers/generation/round3/answer_generation_prompt.md'
OUTPUT_FILE = ROOT / 'Answers/annotation/regenerate_answer_only_answers.json'
ERRORS_FILE = ROOT / 'Answers/annotation/regenerate_answer_only_answers_errors.jsonl'

OPENROUTER_API_URL = 'https://openrouter.ai/api/v1/chat/completions'
MODEL = 'google/gemini-2.5-pro-preview'
TEMPERATURE = 0.4
MAX_TOKENS = 8192
MAX_RETRIES = 3
RETRY_SLEEP = 2.0
REQUIRED_FIELDS = {'answer', 'unanswerable', 'claims'}


def load_prompt(path: Path):
    text = path.read_text(encoding='utf-8')
    system_match = re.search(r"## System message\\s*\\n(.*?)(?=\\n## |\\Z)", text, re.DOTALL)
    user_match = re.search(r"## User message\\s*\\n(.*?)(?=\\n## |\\Z)", text, re.DOTALL)
    if not system_match or not user_match:
        raise ValueError('Prompt file missing required sections')
    return system_match.group(1).strip(), user_match.group(1).strip()


def extract_json_object(text: str) -> Optional[Dict[str, Any]]:
    text = re.sub(r"```(?:json)?\\s*", "", text).strip()
    try:
        return json.loads(text)
    except json.JSONDecodeError:
        pass
    m = re.search(r"\\{.*\\}", text, re.DOTALL)
    if m:
        try:
            return json.loads(m.group(0))
        except json.JSONDecodeError:
            pass
    return None


def call_openrouter(api_key: str, system_prompt: str, user_message: str):
    headers = {
        'Authorization': f'Bearer {api_key}',
        'Content-Type': 'application/json',
    }
    site_url = os.getenv('OPENROUTER_SITE_URL')
    app_name = os.getenv('OPENROUTER_APP_NAME')
    if site_url:
        headers['HTTP-Referer'] = site_url
    if app_name:
        headers['X-Title'] = app_name

    payload = {
        'model': MODEL,
        'messages': [
            {'role': 'system', 'content': system_prompt},
            {'role': 'user', 'content': user_message},
        ],
        'temperature': TEMPERATURE,
        'max_tokens': MAX_TOKENS,
        'reasoning': {'effort': 'low'},
    }

    last_error = 'Unknown API error'
    for attempt in range(1, MAX_RETRIES + 1):
        try:
            r = requests.post(OPENROUTER_API_URL, headers=headers, json=payload, timeout=180)
            if r.status_code != 200:
                last_error = f'HTTP {r.status_code}: {r.text[:400]}'
                if r.status_code in (400, 401, 402, 403):
                    return None, last_error
            else:
                data = r.json()
                choices = data.get('choices', [])
                if choices:
                    choice = choices[0]
                    finish_reason = str(choice.get('finish_reason') or '')
                    content = str(choice.get('message', {}).get('content', '')).strip()
                    if finish_reason == 'length':
                        return content or None, 'Response truncated (finish_reason=length)' if not content else None
                    if content:
                        return content, None
                last_error = 'Empty content in response'
        except Exception as exc:
            last_error = str(exc)

        if attempt < MAX_RETRIES:
            time.sleep(RETRY_SLEEP * attempt)

    return None, last_error


api_key = os.getenv('OPENROUTER_API_KEY', '').strip()
if not api_key:
    raise SystemExit('OPENROUTER_API_KEY not set')

records = json.loads(INPUT_FILE.read_text(encoding='utf-8'))
system_prompt, user_template = load_prompt(PROMPT_FILE)

results = []
errors = []

for rec in records:
    rid = rec['record_id']
    t0 = time.time()
    user_message = user_template.replace('{NUMBERED_TEXT}', rec['text']).replace('{QUESTION}', rec['question'])

    content, api_err = call_openrouter(api_key, system_prompt, user_message)
    if not content:
        errors.append({'record_id': rid, 'error': api_err or 'Empty response'})
        continue

    parsed = extract_json_object(content)
    if not parsed:
        errors.append({'record_id': rid, 'error': f'JSON parse failed; raw={content[:300]}'})
        continue

    missing = REQUIRED_FIELDS - set(parsed.keys())
    if missing:
        errors.append({'record_id': rid, 'error': f'Missing fields {sorted(missing)}; raw={content[:300]}'})
        continue

    results.append({
        'record_id': rec['record_id'],
        'source': rec.get('source', ''),
        'doc_id': rec.get('doc_id', ''),
        'question': rec.get('question', ''),
        'reasoning': parsed.get('reasoning', ''),
        'answer': parsed.get('answer', ''),
        'unanswerable': parsed.get('unanswerable', False),
        'expected_location_hint': parsed.get('expected_location_hint'),
        'claims': parsed.get('claims', []),
        '_generation_seconds': round(time.time() - t0, 2),
    })

OUTPUT_FILE.write_text(json.dumps(results, ensure_ascii=False, indent=2), encoding='utf-8')
with ERRORS_FILE.open('w', encoding='utf-8') as f:
    for e in errors:
        f.write(json.dumps(e, ensure_ascii=False) + '\n')

print(f'Wrote {len(results)} results to {OUTPUT_FILE}')
print(f'Wrote {len(errors)} errors to {ERRORS_FILE}')
PY","explanation":"Generate answers for the 2 regenerate-only records using round3 answer prompt and OpenRouter","goal":"Produce answer-generation output file for user-provided two records","mode":"sync","timeout":600000}

